-- Generated by tools/build-class-trainer.py from Ascension's ability list.
-- Each trainer serves its own class and uses skill line 0 so the client displays services.

-- Add the custom trainer class filter on upstream schemas; skip if already present.
SET @trainer_spell_classmask_ddl = IF(
    EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
        AND TABLE_NAME = 'trainer_spell' AND COLUMN_NAME = 'ClassMask'),
    'SELECT 1',
    'ALTER TABLE `trainer_spell` ADD COLUMN `ClassMask` INT UNSIGNED NOT NULL DEFAULT 0'
);
PREPARE trainer_spell_classmask_stmt FROM @trainer_spell_classmask_ddl;
EXECUTE trainer_spell_classmask_stmt;
DEALLOCATE PREPARE trainer_spell_classmask_stmt;

UPDATE `creature_template` SET `npcflag` = 17 WHERE `entry` IN (98000, 98001);
UPDATE `trainer` SET `Type` = 0, `Requirement` = 12 WHERE `Id` = 98000;
UPDATE `trainer` SET `Type` = 0, `Requirement` = 13 WHERE `Id` = 98001;

DELETE FROM `trainer_spell` WHERE `TrainerId` = 98000;

DELETE FROM `trainer_spell` WHERE `TrainerId` = 98001;

-- Refresh the fixed level-one spell kit independently of trainer rank levels.
DELETE FROM `playercreateinfo_spell_custom` WHERE `raceMask` = 0 AND `classMask` IN (2048, 4096);
